ConfigScreenViewBase::~ConfigScreenViewBase()
{

}

void ConfigScreenViewBase::setupScreen()
{
    barraConteiner1.initialize();
    scrollList2.initialize();
    for (int i = 0; i < scrollList2ListItems.getNumberOfDrawables(); i++)
    {
        scrollList2ListItems[i].initialize();
    }
    wheelYear.initialize();
    for (int i = 0; i < wheelYearListItems.getNumberOfDrawables(); i++)
    {
        wheelYearListItems[i].initialize();
    }
    wheelHour.initialize();
    for (int i = 0; i < wheelHourListItems.getNumberOfDrawables(); i++)
    {
        wheelHourListItems[i].initialize();
    }
    wheelDay.initialize();
    for (int i = 0; i < wheelDayListItems.getNumberOfDrawables(); i++)
    {
        wheelDayListItems[i].initialize();
    }
    wheelMin.initialize();
    for (int i = 0; i < wheelMinListItems.getNumberOfDrawables(); i++)
    {
        wheelMinListItems[i].initialize();
    }
    wheelMonth.initialize();
    for (int i = 0; i < wheelMonthListItems.getNumberOfDrawables(); i++)
    {
        wheelMonthListItems[i].initialize();
    }
    teclado1Container.initialize();
    savedContainer1.initialize();
}

void ConfigScreenViewBase::flexButtonCallbackHandler(const touchgfx::AbstractButtonContainer& src)
{
    if (&src == &flexButton1)
    {
        //Interaction1
        //When flexButton1 clicked change screen to RunScreen
        //Go to RunScreen with screen transition towards North
        application().gotoRunScreenScreenSlideTransitionNorth();
    }
}

void ConfigScreenViewBase::buttonCallbackHandler(const touchgfx::AbstractButton& src)
{
    if (&src == &buttonBack)
    {
        //Interaction2
        //When buttonBack clicked change screen to RunScreen
        //Go to RunScreen with screen transition towards East
        application().gotoRunScreenScreenSlideTransitionEast();
    }
}

void ConfigScreenViewBase::updateItemCallbackHandler(touchgfx::DrawableListItemsInterface* items, int16_t containerIndex, int16_t itemIndex)
{
    if (items == &scrollList2ListItems)
    {
        scrollList2UpdateItem(scrollList2ListItems[containerIndex], itemIndex);
    }

    if (items == &wheelYearListItems)
    {
        touchgfx::Drawable* d = items->getDrawable(containerIndex);
        DataHoraContainer* cc = (DataHoraContainer*)d;
        wheelYearUpdateItem(*cc, itemIndex);
    }

    if (items == &wheelHourListItems)
    {
        touchgfx::Drawable* d = items->getDrawable(containerIndex);
        DataHoraContainer* cc = (DataHoraContainer*)d;
        wheelHourUpdateItem(*cc, itemIndex);
    }

    if (items == &wheelDayListItems)
    {
        touchgfx::Drawable* d = items->getDrawable(containerIndex);
        DataHoraContainer* cc = (DataHoraContainer*)d;
        wheelDayUpdateItem(*cc, itemIndex);
    }

    if (items == &wheelMinListItems)
    {
        touchgfx::Drawable* d = items->getDrawable(containerIndex);
        DataHoraContainer* cc = (DataHoraContainer*)d;
        wheelMinUpdateItem(*cc, itemIndex);
    }

    if (items == &wheelMonthListItems)
    {
        touchgfx::Drawable* d = items->getDrawable(containerIndex);
        DataHoraContainer* cc = (DataHoraContainer*)d;
        wheelMonthUpdateItem(*cc, itemIndex);
    }
}
